import React, { useState } from 'react'
import styled from 'styled-components'
import { dateFormat } from '../../utils/dateFormat';
import { bitcoin, book, calender, card, circle, clothing, comment, dollar, food, freelance, medical, money, piggy, stocks, takeaway, trash, tv, users, yt, edit, Investor, Land, Machine } from '../../utils/Icons';
import Button from '../Button/Button';

function ExpenseItem({
    id,
    title,
    amount,
    date,
    category,
    description,
    deleteItem,
    updateItem,
    indicatorColor,
    type
}) {

    const categoryIcon = () =>{
        switch(category) {
            case 'salary':
                return Investor;
            case 'freelancing':
                return Machine;
            case 'investments':
                return Land;
            case 'stocks':
                return tv;
            case 'other':
                return piggy;
            default:
                return ''
        }
    }

    const expenseCatIcon = () => {
        switch (category) {
            case 'Investor':
                            return Investor;
                        case 'Machine':
                            return Machine;
                        case 'HR':
                            return users;
                        case 'Land':
                            return Land;
                        case 'Other':
                            return book;
                        default:
                            return ''
        }
    }

    const [isPopupOpen, setIsPopupOpen] = useState(false);
    const [updatedIncome, setUpdatedIncome] = useState({
        title,
        amount,
        category,
        description,
        date,
    });

    const handleUpdateClick = () => {
        setIsPopupOpen(true);
    };

    const handleClosePopup = () => {
        setIsPopupOpen(false);
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setUpdatedIncome({ ...updatedIncome, [name]: value });
    };

    const handleUpdateSubmit = () => {
        updateItem(id, updatedIncome);
        setIsPopupOpen(false);
        window.location.reload();
    };

    console.log('type', type)

    return (
        <IncomeItemStyled indicator={indicatorColor}>
            {/* Icon */}
    <div className="icon">
        {type === 'expense' ? expenseCatIcon() : categoryIcon()}
    </div>

    {/* Content */}
    <div className="content">
        {/* Title */}
        <h5>{title}</h5>

        {/* Amount, Date & Buttons */}
        <div className="row">
            <p>{dollar} {amount}</p>
            <p>{calender} {dateFormat(date)}</p>
            <div className="btn-group">
                <Button 
                    icon={edit}
                    bPad={'1rem'}
                    bRad={'50%'}
                    bg={'var(--primary-color)'}
                    color={'#fff'}
                    iColor={'#fff'}
                    hColor={'var(--color-green)'}
                    onClick={handleUpdateClick}
                />
                <Button 
                    icon={trash}
                    bPad={'1rem'}
                    bRad={'50%'}
                    bg={'var(--primary-color)'}
                    color={'#fff'}
                    iColor={'#fff'}
                    hColor={'var(--color-green)'}
                    onClick={() => deleteItem(id)}
                />
            </div>
        </div>

        {/* Description (Now Correctly Placed!) */}
        <p className="description">
            {comment} {description}
        </p>
    </div>
            

            {/* Update Popup */}
            {isPopupOpen && (
                <PopupStyled>
                    <div className="popup">
                        <h3>Update Income</h3>
                        <input type="text" name="title" value={updatedIncome.title} onChange={handleInputChange} placeholder="Title" />
                        <input type="number" name="amount" value={updatedIncome.amount} onChange={handleInputChange} placeholder="Amount" />
                        <input type="text" name="category" value={updatedIncome.category} onChange={handleInputChange} placeholder="Category" />
                        <input type="text" name="description" value={updatedIncome.description} onChange={handleInputChange} placeholder="Description" />
                        <input type="date" name="date" value={updatedIncome.date} onChange={handleInputChange} />
                        <div className="buttons">
                            <button onClick={handleUpdateSubmit}>Update</button>
                            <button onClick={handleClosePopup}>Close</button>
                        </div>
                    </div>
                </PopupStyled>
            )}
        </IncomeItemStyled>
    )
}

const IncomeItemStyled = styled.div`
  background: #fcf6f9;
  border: 2px solid #ffffff;
  box-shadow: 0px 1px 15px rgba(0, 0, 0, 0.06);
  border-radius: 20px;
  padding: 1rem;
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  width: 100%;
  color: #222260;

  .icon {
    width: 80px;
    height: 80px;
    border-radius: 20px;
    background: #f5f5f5;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 2px solid #ffffff;
  }

  .content {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;

    h5 {
      font-size: 1.3rem;
      padding-left: 2rem;
      position: relative;

      &::before {
        content: "";
        position: absolute;
        left: 0;
        top: 50%;
        transform: translateY(-50%);
        width: 0.8rem;
        height: 0.8rem;
        border-radius: 50%;
        background: ${(props) => props.indicator};
      }
    }

    .row {
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;

      p {
        display: flex;
        align-items: center;
        gap: 0.5rem;
        color: var(--primary-color);
        opacity: 0.8;
      }

      .btn-group {
        display: flex;
        gap: 0.5rem;
      }
    }

    .description {
      color: var(--primary-color);
      opacity: 0.8;
      max-width: 100%;
      overflow-wrap: break-word;
      word-wrap: break-word;
    }
  }
`;

const PopupStyled = styled.div`
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 10000;
    
    .popup {
        background: white;
        padding: 20px;
        border-radius: 10px;
        width: 400px;
        text-align: center;
    }
    
    input {
        width: 100%;
        padding: 10px;
        margin: 10px 0;
        border: 1px solid #ccc;
        border-radius: 5px;
    }
    
    .buttons {
        display: flex;
        justify-content: space-between;
    }

    button {
        padding: 10px;
        border: none;
        cursor: pointer;
        border-radius: 5px;
        width: 45%;
    }

    button:first-child {
        background: green;
        color: white;
    }

    button:last-child {
        background: red;
        color: white;
    }
`;


export default ExpenseItem
